/// <summary>
/// Extension of executeQuery method
/// </summary>
public void executeQuery()
{
    element.avaSetActiveQueryRanges();

    next executeQuery();
}

/// <summary>
/// NDX
/// </summary>
void linkActive()
{
    if (element.icAgreement)
    {
        element.relationType = PriceType::PriceSales;
        element.initRelation();
        element.initRecord();
        element.updateDesign(InventDimFormDesignUpdate::LinkActive);
    }
    next linkActive();
}
